//! Statement and expression rendering (`toJava`) and statement matching
//! against vectors from the real Vineflower 1.12.0 classes
//! (`data/b04/B04Oracle.java` -> `data/b04/b04_golden.txt`, regenerated by
//! `data/b04/gen.sh`). Each scenario mirrors the Java driver statement by
//! statement, so statement ids (and the labels printed from them) line up.

use kuna_jvm::assert_exprent::AssertExprent;
use kuna_jvm::basic_block_statement::BasicBlockStatement;
use kuna_jvm::catch_all_statement::CatchAllStatement;
use kuna_jvm::do_statement::{DoStatement, Type as LoopType};
use kuna_jvm::exit_exprent::{ExitExprent, Type as ExitType};
use kuna_jvm::exprent::Exprent;
use kuna_jvm::field_descriptor::FieldDescriptor;
use kuna_jvm::field_exprent::FieldExprent;
use kuna_jvm::general_statement::GeneralStatement;
use kuna_jvm::i_matchable::IMatchable;
use kuna_jvm::if_exprent::{IfExprent, Type as IfType};
use kuna_jvm::if_statement::IfStatement;
use kuna_jvm::list_stack::ListStack;
use kuna_jvm::match_engine::MatchEngine;
use kuna_jvm::match_node::MatchValue;
use kuna_jvm::monitor_exprent::{MonitorExprent, Type as MonitorType};
use kuna_jvm::rt::JList;
use kuna_jvm::sequence_statement::SequenceStatement;
use kuna_jvm::stat_edge::StatEdge;
use kuna_jvm::statement::Statement;
use kuna_jvm::struct_method::StructMethod;
use kuna_jvm::switch_exprent::SwitchExprent;
use kuna_jvm::switch_head_exprent::SwitchHeadExprent;
use kuna_jvm::switch_statement::SwitchStatement;
use kuna_jvm::synchronized_statement::SynchronizedStatement;
use kuna_jvm::text_buffer::TextBuffer;
use kuna_jvm::var_type::VarType;
use kuna_jvm::yield_exprent::YieldExprent;

use crate::common;
use crate::k2_dom_helper::{fixture_method, start_method};

const GOLDEN: &str = include_str!("data/b04/b04_golden.txt");

const REG: i32 = StatEdge::TYPE_REGULAR;
const BREAK: i32 = StatEdge::TYPE_BREAK;
const CONTINUE: i32 = StatEdge::TYPE_CONTINUE;

fn af() -> Exprent {
    AssertExprent::new(vec![None]).0
}

fn mexit() -> Exprent {
    MonitorExprent::new(MonitorType::Exit, af(), None).0
}

fn if_expr(condition: Exprent) -> Exprent {
    let mut stack = ListStack::new();
    stack.push(condition);
    IfExprent::new(IfType::Value, &mut stack, None).0
}

fn field(name: &str) -> Exprent {
    FieldExprent::new(
        name.to_string(),
        "pkg/E".to_string(),
        true,
        None,
        FieldDescriptor::parse_descriptor("Lpkg/E;"),
        None,
    )
    .0
}

fn bb() -> Statement {
    BasicBlockStatement::create().0
}

fn add(stat: Statement, exprent: Exprent) {
    stat.get_exprents()
        .expect("basic block exprents")
        .add(exprent);
}

fn edge(type_: i32, source: Statement, destination: Statement) -> StatEdge {
    let e = StatEdge::new(type_, source, destination);
    source.add_successor(e);
    e
}

fn edge_c(
    type_: i32,
    source: Statement,
    destination: Statement,
    closure: Option<Statement>,
) -> StatEdge {
    let e = StatEdge::new_closure(type_, source, destination, closure);
    source.add_successor(e);
    e
}

fn values(values: Vec<Option<Exprent>>) -> JList<Option<Exprent>> {
    JList::from(values)
}

struct Oracle {
    out: String,
    mt: StructMethod,
}

impl Oracle {
    fn reset(&self) {
        start_method(self.mt);
    }

    fn out(&mut self, name: &str, render: impl FnOnce() -> TextBuffer) {
        self.out.push_str("== ");
        self.out.push_str(name);
        self.out.push('\n');
        self.out
            .push_str(&render().convert_to_string_and_allow_data_discard());
        self.out.push_str("\n<<\n");
    }

    fn match_(&mut self, name: &str, target: &dyn IMatchable, vars: &[&str], description: &[&str]) {
        let engine = MatchEngine::new(description);
        let res = engine.match_(target);
        self.out.push_str(&format!("match {name} {res}"));
        for v in vars {
            let value = match engine.get_variable_value(v) {
                None => "null".to_string(),
                Some(MatchValue::Statement(s)) => s.id().to_string(),
                Some(other) => panic!("unexpected variable value {other:?}"),
            };
            self.out.push_str(&format!(" {v}={value}"));
        }
        self.out.push('\n');
    }
}

fn render_all() -> String {
    let mut o = Oracle {
        out: String::new(),
        mt: fixture_method(),
    };

    o.reset();
    {
        let (h, t, out) = (bb(), bb(), bb());
        add(h, af());
        let general = GeneralStatement::new(h, vec![h, t], None);
        edge(REG, h, t);
        edge_c(BREAK, h, out, Some(general.0));
        let ifs = IfStatement::new(h, 1, None);
        ifs.get_headexprent_list().add(if_expr(af()));
        general.collapse_nodes_to_statement(ifs.0);
        o.out("if_break", || general.0.to_java(0));
    }

    o.reset();
    {
        let (h, i, h2, x, out2, p) = (bb(), bb(), bb(), bb(), bb(), bb());
        add(h, af());
        add(i, mexit());
        add(x, af());
        edge(REG, h2, x);
        let brk = edge_c(BREAK, h2, out2, None);
        brk.with_mut(|d| d.labeled = false);
        let inner = IfStatement::new(h2, 1, None);
        inner.get_headexprent_list().add(if_expr(af()));
        edge(REG, h, inner.0);
        edge(REG, h, i);
        edge(REG, i, p);
        let ip = edge(REG, inner.0, p);
        ip.with_mut(|d| d.explicit = false);
        let outer = IfStatement::new(h, 2, Some(p));
        outer.get_headexprent_list().add(if_expr(af()));
        o.out("if_else_if", || outer.0.to_java(0));
    }

    o.reset();
    {
        let (h, i, e, p) = (bb(), bb(), bb(), bb());
        add(h, af());
        add(i, af());
        add(e, mexit());
        edge(REG, h, e);
        edge(REG, h, i);
        edge(REG, i, p);
        edge(REG, e, p);
        let ifs = IfStatement::new(h, 2, Some(p));
        ifs.get_headexprent_list().add(if_expr(af()));
        o.out("if_else", || ifs.0.to_java(1));
        o.match_(
            "if_ifelse",
            &ifs.0,
            &["$i$"],
            &[
                "statement type:if iftype:ifelse",
                " statement position:1 ret:$i$",
            ],
        );
        o.match_("if_if", &ifs.0, &[], &["statement type:if iftype:if"]);
        o.match_(
            "if_neg",
            &ifs.0,
            &["$e$"],
            &[
                "statement type:if",
                " statement position:-1 exprsize:1 ret:$e$",
            ],
        );
    }

    o.reset();
    {
        let ifs = IfStatement::new_empty();
        let first = bb();
        ifs.set_first(first);
        ifs.get_stats().borrow_mut().add_with_key(first, first.id());
        let dest = bb();
        ifs.set_if_edge(Some(edge(CONTINUE, first, dest)));
        o.out("if_null_condition", || ifs.0.to_java(0));
    }

    for (type_, name) in [
        (LoopType::Infinite, "infinite"),
        (LoopType::DoWhile, "do_while"),
        (LoopType::While, "while"),
        (LoopType::For, "for"),
        (LoopType::ForEach, "for_each"),
    ] {
        o.reset();
        let head = bb();
        add(head, af());
        let d = DoStatement::new(head);
        d.set_looptype(type_);
        match type_ {
            LoopType::Infinite => {
                edge_c(CONTINUE, head, d.0, Some(d.0));
            }
            LoopType::DoWhile | LoopType::While => d.set_condition_exprent(af()),
            LoopType::For => {
                d.set_init_exprent(mexit());
                d.set_condition_exprent(af());
                d.set_inc_exprent(mexit());
            }
            LoopType::ForEach => {
                d.set_init_exprent(af());
                d.set_inc_exprent(mexit());
            }
        }
        o.out(&format!("do_{name}"), || d.0.to_java(1));
    }

    o.reset();
    {
        let head = bb();
        let d = DoStatement::new(head);
        d.set_looptype(LoopType::For);
        d.set_condition_exprent(af());
        d.set_inc_exprent(mexit());
        o.out("do_for_no_init", || d.0.to_java(0));
    }

    o.reset();
    {
        let (h, c1, c2, d) = (bb(), bb(), bb(), bb());
        add(h, af());
        add(c1, af());
        add(c2, mexit());
        add(d, af());
        let e1 = edge(REG, h, c1);
        let e2 = edge(REG, h, c2);
        let e3 = edge(REG, h, c2);
        let ed = edge(REG, h, d);
        let sw = SwitchStatement::new(h, None);
        sw.set_default_edge(Some(ed));
        sw.get_case_statements().add_all(vec![c1, c2, d]);
        sw.get_case_edges().add(JList::from(vec![e1]));
        sw.get_case_edges().add(JList::from(vec![e2, e3]));
        sw.get_case_edges().add(JList::from(vec![ed]));
        sw.get_case_values().add(values(vec![Some(field("A"))]));
        sw.get_case_values()
            .add(values(vec![Some(field("B")), Some(field("C"))]));
        sw.get_case_values().add(values(vec![None]));
        sw.get_case_guards().add(None);
        sw.get_case_guards().add(Some(af()));
        sw.scope_case_statement(c2);
        sw.get_headexprent_list()
            .add(SwitchHeadExprent::new(af(), None).0);
        o.out("switch", || sw.0.to_java(0));
        sw.set_phantom(true);
        o.out("switch_phantom", || sw.0.to_java(0));
    }

    o.reset();
    {
        let (h, c1, c2, c3, c4, d, after) = (bb(), bb(), bb(), bb(), bb(), bb(), bb());
        add(c1, YieldExprent::new(af(), VarType::VARTYPE_INT()).0);
        add(c2, af());
        add(c2, mexit());
        add(c3, af());
        add(
            c4,
            ExitExprent::new(ExitType::Throw, Some(af()), None, None, None).0,
        );
        let e1 = edge(REG, h, c1);
        let e2 = edge(REG, h, c2);
        let e3 = edge(REG, h, c3);
        let e4 = edge(REG, h, c4);
        let ed = edge(REG, h, d);
        edge_c(BREAK, d, after, None);
        let sw = SwitchStatement::new(h, None);
        sw.set_default_edge(Some(ed));
        sw.get_case_statements().add_all(vec![c1, c2, c3, c4, d]);
        for e in [e1, e2, e3, e4, ed] {
            sw.get_case_edges().add(JList::from(vec![e]));
        }
        sw.get_case_values().add(values(vec![Some(field("A"))]));
        sw.get_case_values().add(values(vec![Some(field("B"))]));
        sw.get_case_values().add(values(vec![Some(field("C"))]));
        sw.get_case_values()
            .add(values(vec![Some(field("D")), Some(field("E"))]));
        sw.get_case_values().add(values(vec![None]));
        sw.get_case_guards().add(None);
        sw.get_case_guards().add(None);
        sw.get_case_guards().add(Some(af()));
        sw.get_headexprent_list()
            .add(SwitchHeadExprent::new(af(), None).0);
        sw.set_phantom(true);
        let se = SwitchExprent::new(sw, VarType::VARTYPE_INT(), false, false);
        o.out("switch_expr", || se.0.to_java(1));
    }

    o.reset();
    {
        let (h, c1, c2) = (bb(), bb(), bb());
        add(c1, af());
        add(c2, mexit());
        let e1 = edge(REG, h, c1);
        let e2 = edge(REG, h, c2);
        let ed = edge(REG, h, c2);
        let sw = SwitchStatement::new(h, None);
        sw.set_default_edge(Some(ed));
        sw.get_case_statements().add_all(vec![c1, c2]);
        sw.get_case_edges().add(JList::from(vec![e1]));
        sw.get_case_edges().add(JList::from(vec![e2, ed]));
        sw.get_case_values().add(values(vec![Some(field("A"))]));
        sw.get_case_values()
            .add(values(vec![Some(field("B")), None]));
        sw.get_headexprent_list()
            .add(SwitchHeadExprent::new(af(), None).0);
        sw.set_phantom(true);
        let se = SwitchExprent::new(sw, VarType::VARTYPE_INT(), false, true);
        o.out("switch_expr_default", || se.0.to_java(0));
    }

    o.reset();
    {
        let (head, body, exc) = (bb(), bb(), bb());
        add(head, af());
        add(body, af());
        let s = SynchronizedStatement::new(head, body, exc);
        s.get_headexprent_list()
            .add(MonitorExprent::new(MonitorType::Enter, af(), None).0);
        o.out("sync", || s.0.to_java(1));
        let bare = SynchronizedStatement::new(bb(), bb(), bb());
        o.out("sync_null_head", || bare.0.to_java(0));
    }

    o.reset();
    {
        let (head, handler) = (bb(), bb());
        add(head, af());
        add(handler, mexit());
        let ca = CatchAllStatement::new(head, handler);
        ca.set_finally(true);
        o.out("finally", || ca.0.to_java(1));
    }

    o.reset();
    {
        let (a, b, c, out) = (bb(), bb(), bb(), bb());
        add(a, af());
        add(b, mexit());
        let seq = SequenceStatement::new(vec![a, c, b]);
        edge_c(BREAK, b, out, Some(seq.0));
        o.out("sequence", || seq.0.to_java(1));
        let target = &seq.0;
        o.match_(
            "seq_size",
            target,
            &[],
            &["statement type:sequence statsize:3"],
        );
        o.match_(
            "seq_size_wrong",
            target,
            &[],
            &["statement type:sequence statsize:2"],
        );
        o.match_("seq_type_wrong", target, &[], &["statement type:if"]);
        o.match_(
            "seq_children",
            target,
            &["$s$", "$a$", "$c$"],
            &[
                "statement type:sequence ret:$s$",
                " statement type:basicblock exprsize:1 ret:$a$",
                " statement type:basicblock exprsize:0 ret:$c$",
            ],
        );
        o.match_(
            "seq_last",
            target,
            &["$x$"],
            &[
                "statement type:sequence",
                " statement position:-1 exprsize:1 ret:$x$",
            ],
        );
        o.match_(
            "seq_first_wrong",
            target,
            &[],
            &[
                "statement type:sequence",
                " statement position:0 exprsize:0",
            ],
        );
        o.match_(
            "seq_null_exprents",
            target,
            &[],
            &["statement type:sequence", " statement exprsize:-1"],
        );
        o.match_(
            "seq_too_many",
            target,
            &[],
            &[
                "statement",
                " statement",
                " statement",
                " statement",
                " statement",
            ],
        );
        o.match_(
            "seq_same_var",
            target,
            &["$v$"],
            &["statement", " statement ret:$v$", " statement ret:$v$"],
        );
        o.match_(
            "bb_on_seq",
            target,
            &[],
            &["statement type:basicblock exprsize:1"],
        );
    }

    o.reset();
    {
        let (a, b, c) = (bb(), bb(), bb());
        add(a, af());
        add(b, mexit());
        add(c, af());
        let seq = SequenceStatement::new(vec![a, b, c]);
        o.out("sequence_plain", || seq.0.to_java(0));
    }

    o.reset();
    {
        let (a, out) = (bb(), bb());
        add(a, af());
        edge_c(BREAK, a, out, Some(a));
        o.out("basic_block_labeled", || a.to_java(1));
    }

    o.out
}

/// Splits the oracle output into `== name ... <<` blocks and `match` lines.
fn records(text: &str) -> Vec<String> {
    let mut records = Vec::new();
    let mut block: Option<String> = None;
    for line in text.lines() {
        match &mut block {
            Some(b) => {
                b.push_str(line);
                b.push('\n');
                if line == "<<" {
                    records.push(block.take().expect("open block"));
                }
            }
            None if line.starts_with("== ") => block = Some(format!("{line}\n")),
            None => records.push(line.to_string()),
        }
    }
    assert!(block.is_none(), "unterminated block");
    records
}

#[test]
fn renders_and_matches_like_vineflower() {
    let _context = common::install_default_context();
    let actual = render_all();

    let expected = records(GOLDEN);
    let actual = records(&actual);
    assert_eq!(expected.len(), actual.len(), "record count");
    let mut mismatches = Vec::new();
    for (e, a) in expected.iter().zip(&actual) {
        if e != a {
            mismatches.push(format!("java:\n{e}\nrust:\n{a}"));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}

#[test]
fn signed_integer_positions() {
    let _context = common::install_default_context();
    let mt = fixture_method();
    start_method(mt);
    let (a, b) = (bb(), bb());
    let seq = SequenceStatement::new(vec![a, b]);
    for (position, expected) in [("-1", b), ("-4", a), ("3", b)] {
        let pattern = format!(" statement position:{position} ret:$x$");
        let engine = MatchEngine::new(&["statement", &pattern]);
        assert!(engine.match_(&seq.0), "position {position}");
        let Some(MatchValue::Statement(x)) = engine.get_variable_value("$x$") else {
            panic!("$x$ unbound for position {position}");
        };
        assert_eq!(x, expected, "position {position}");
    }

    let negative = kuna_jvm::rt::try_catch(|| {
        MatchEngine::new(&["statement", " statement position:-5"]).match_(&seq.0)
    });
    let caught = negative.expect_err("(2 + -5) % 2 is -1");
    assert!(caught.is("IndexOutOfBoundsException"), "{}", caught.message);

    let not_a_number = MatchEngine::new(&["statement", " statement position:+1"]);
    assert!(!not_a_number.match_(&seq.0));
}
